package lf.sandbox.time.auth;

import java.util.Map;
import java.util.UUID;
import java.util.regex.Pattern;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class AuthController {

    private static final Map<String, String> GENERIC_ERROR = Map.of("error", "SBX-E-GENERIC");
    private static final Pattern EMAIL_PATTERN =
            Pattern.compile("^[^@\\s.]+(?:\\.[^@\\s.]+)*@[^@\\s.]+(?:\\.[^@\\s.]+)+$");

    private final AuthService authService;
    private final AuthUser authUser;
    private final BCryptPasswordEncoder passwordEncoder;
    private final String demoEmail;

    public AuthController(
            AuthService authService,
            AuthUser authUser,
            BCryptPasswordEncoder passwordEncoder,
            @Value("${app.auth.b2b-demo-email:demo@sandbox.test}") String demoEmail) {
        this.authService = authService;
        this.authUser = authUser;
        this.passwordEncoder = passwordEncoder;
        this.demoEmail = demoEmail;
    }

    @PostMapping("/api/auth/login")
    public ResponseEntity<?> login(@RequestBody(required = false) Map<String, Object> body) {
        if (body != null && body.containsKey("email")) {
            return loginWithEmail(body);
        }
        if (body == null
                || !(body.get("username") instanceof String username)
                || !(body.get("password") instanceof String password)) {
            return unauthorized();
        }
        return authService
                .login(username, password)
                .<ResponseEntity<?>>map(login -> ResponseEntity.ok(
                        new LoginResponse(login.token(), login.expiresAt().toString())))
                .orElseGet(AuthController::unauthorized);
    }

    private ResponseEntity<?> loginWithEmail(Map<String, Object> body) {
        String correlationId = UUID.randomUUID().toString();
        if (!(body.get("email") instanceof String suppliedEmail)
                || !(body.get("password") instanceof String password)) {
            return invalidCredentials(correlationId);
        }
        String email = suppliedEmail.strip();
        if (password.isEmpty()) {
            return invalidCredentials(correlationId);
        }
        try {
            boolean emailMatches =
                    email.length() <= 254 && EMAIL_PATTERN.matcher(email).matches() && matchesConfiguredEmail(email);
            if (!emailMatches) {
                // Execute the same password-hash work without creating a session.
                passwordEncoder.matches(password, authUser.passwordBcrypt());
                return invalidCredentials(correlationId);
            }
            return authService
                    .login(authUser.username(), password)
                    .<ResponseEntity<?>>map(login ->
                            ResponseEntity.ok(new B2bLoginResponse("AUTHENTICATED", correlationId, login.token())))
                    .orElseGet(() -> invalidCredentials(correlationId));
        } catch (RuntimeException exception) {
            return ResponseEntity.status(503)
                    .body(new B2bLoginFailure("SERVICE_UNAVAILABLE", correlationId, "SBX-B2B-E-NETWORK"));
        }
    }

    private boolean matchesConfiguredEmail(String email) {
        int at = email.lastIndexOf('@');
        int configuredAt = demoEmail.lastIndexOf('@');
        return at > 0
                && configuredAt > 0
                && email.substring(0, at).equals(demoEmail.substring(0, configuredAt))
                && email.substring(at + 1).equalsIgnoreCase(demoEmail.substring(configuredAt + 1));
    }

    private static ResponseEntity<?> invalidCredentials(String correlationId) {
        return ResponseEntity.status(401)
                .body(new B2bLoginFailure("INVALID_CREDENTIALS", correlationId, "SBX-B2B-E-CREDENTIALS"));
    }

    @GetMapping("/api/auth/session")
    public ResponseEntity<?> session(@RequestHeader(name = "Authorization", required = false) String authorization) {
        return authService
                .session(authorization)
                .<ResponseEntity<?>>map(username -> ResponseEntity.ok(new SessionResponse(username)))
                .orElseGet(AuthController::unauthorized);
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<Map<String, String>> invalidLoginBody() {
        return ResponseEntity.status(401).body(GENERIC_ERROR);
    }

    private static ResponseEntity<?> unauthorized() {
        return ResponseEntity.status(401).body(GENERIC_ERROR);
    }

    public record LoginResponse(String token, String expiresAt) {}

    public record SessionResponse(String username) {}

    public record B2bLoginResponse(String outcome, String correlation_id, String token) {}

    public record B2bLoginFailure(String outcome, String correlation_id, String error_code) {}
}

package lf.sandbox.time.auth;

import java.security.SecureRandom;
import java.time.Clock;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;

@Service
public class AuthService {

    private static final int TOKEN_BYTES = 32;

    private final AuthUser user;
    private final BCryptPasswordEncoder passwordEncoder;
    private final Clock clock;
    private final int maxFailedAttempts;
    private final int lockMinutes;
    private final int sessionMinutes;
    private final SecureRandom random = new SecureRandom();
    private final Map<String, Session> sessions = new HashMap<>();

    private int consecutiveFailures;
    private Instant lockedUntil;

    public AuthService(
            AuthUser user,
            BCryptPasswordEncoder passwordEncoder,
            Clock clock,
            @Value("${app.auth.failed-attempts:5}") int maxFailedAttempts,
            @Value("${app.auth.lock-minutes:15}") int lockMinutes,
            @Value("${app.auth.session-minutes:30}") int sessionMinutes) {
        if (maxFailedAttempts <= 0 || lockMinutes <= 0 || sessionMinutes <= 0) {
            throw new IllegalArgumentException("Invalid authentication policy");
        }
        this.user = user;
        this.passwordEncoder = passwordEncoder;
        this.clock = clock;
        this.maxFailedAttempts = maxFailedAttempts;
        this.lockMinutes = lockMinutes;
        this.sessionMinutes = sessionMinutes;
    }

    public synchronized Optional<LoginResult> login(String username, String password) {
        if (username == null || username.isBlank() || password == null || password.isBlank()) {
            return Optional.empty();
        }

        Instant now = clock.instant();
        if (!user.username().equals(username)) {
            return Optional.empty();
        }
        if (lockedUntil != null) {
            if (now.isBefore(lockedUntil)) {
                return Optional.empty();
            }
            lockedUntil = null;
            consecutiveFailures = 0;
        }

        if (!passwordEncoder.matches(password, user.passwordBcrypt())) {
            consecutiveFailures++;
            if (consecutiveFailures >= maxFailedAttempts) {
                lockedUntil = now.plus(lockMinutes, ChronoUnit.MINUTES);
            }
            return Optional.empty();
        }

        consecutiveFailures = 0;
        byte[] randomBytes = new byte[TOKEN_BYTES];
        random.nextBytes(randomBytes);
        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes);
        Instant expiresAt = now.plus(sessionMinutes, ChronoUnit.MINUTES);
        sessions.put(token, new Session(user.username(), expiresAt));
        return Optional.of(new LoginResult(token, expiresAt));
    }

    public synchronized Optional<String> session(String authorization) {
        if (authorization == null || !authorization.startsWith("Bearer ")) {
            return Optional.empty();
        }
        String token = authorization.substring("Bearer ".length());
        if (token.isBlank()) {
            return Optional.empty();
        }

        Session stored = sessions.get(token);
        if (stored == null) {
            return Optional.empty();
        }
        if (!clock.instant().isBefore(stored.expiresAt())) {
            sessions.remove(token);
            return Optional.empty();
        }
        return Optional.of(stored.username());
    }

    public record LoginResult(String token, Instant expiresAt) {}

    private record Session(String username, Instant expiresAt) {}
}

-- Persisted B2B accounts, attempts and sessions.
CREATE TABLE IF NOT EXISTS sbx_b2b_accounts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email varchar(254) NOT NULL CHECK (email = btrim(email) AND email LIKE '%@%' AND split_part(email, '@', 2) = lower(split_part(email, '@', 2))),
    password_hash text NOT NULL CHECK (password_hash ~ '^[$]2[aby][$][0-9]{2}[$][./A-Za-z0-9]{53}$'),
    company_code varchar(32) NOT NULL,
    profile varchar(40) NOT NULL CHECK (profile IN ('SBX_B2B_ADMIN_EMPRESA', 'SBX_B2B_APROBADOR', 'SBX_B2B_OPERADOR', 'SBX_B2B_LECTOR_AUDITOR')),
    status varchar(12) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE', 'RESTRICTED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS sbx_b2b_accounts_lower_idx ON sbx_b2b_accounts (lower(email));

CREATE TABLE IF NOT EXISTS sbx_b2b_login_attempts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id bigint REFERENCES sbx_b2b_accounts(id),
    email_normalized varchar(254) NOT NULL CHECK (email_normalized = lower(btrim(email_normalized))),
    outcome varchar(24) NOT NULL CHECK (outcome IN ('INVALID_CREDENTIALS', 'RATE_LIMITED')),
    correlation_id varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS sbx_b2b_login_attempts_email_normalized_created_at_idx ON sbx_b2b_login_attempts (email_normalized, created_at);

CREATE TABLE IF NOT EXISTS sbx_b2b_sessions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id bigint NOT NULL REFERENCES sbx_b2b_accounts(id),
    token_hash char(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (expires_at > created_at)
);

CREATE OR REPLACE FUNCTION sbx_b2b_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION sbx_b2b_touch_updated_at() FROM PUBLIC;

DROP TRIGGER IF EXISTS sbx_b2b_accounts_updated_at ON sbx_b2b_accounts;
CREATE TRIGGER sbx_b2b_accounts_updated_at BEFORE UPDATE ON sbx_b2b_accounts
    FOR EACH ROW EXECUTE FUNCTION sbx_b2b_touch_updated_at();
DROP TRIGGER IF EXISTS sbx_b2b_sessions_updated_at ON sbx_b2b_sessions;
CREATE TRIGGER sbx_b2b_sessions_updated_at BEFORE UPDATE ON sbx_b2b_sessions
    FOR EACH ROW EXECUTE FUNCTION sbx_b2b_touch_updated_at();

ALTER TABLE sbx_b2b_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE sbx_b2b_login_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE sbx_b2b_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON sbx_b2b_accounts, sbx_b2b_login_attempts, sbx_b2b_sessions FROM PUBLIC;
REVOKE ALL ON SEQUENCE sbx_b2b_accounts_id_seq, sbx_b2b_login_attempts_id_seq, sbx_b2b_sessions_id_seq FROM PUBLIC;

-- Explicit owner-only policies: no privileges are granted to PUBLIC.
DROP POLICY IF EXISTS sbx_b2b_accounts_owner ON sbx_b2b_accounts;
CREATE POLICY sbx_b2b_accounts_owner ON sbx_b2b_accounts TO CURRENT_USER USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS sbx_b2b_login_attempts_owner ON sbx_b2b_login_attempts;
CREATE POLICY sbx_b2b_login_attempts_owner ON sbx_b2b_login_attempts FOR INSERT TO CURRENT_USER WITH CHECK (true);
DROP POLICY IF EXISTS sbx_b2b_login_attempts_read ON sbx_b2b_login_attempts;
CREATE POLICY sbx_b2b_login_attempts_read ON sbx_b2b_login_attempts FOR SELECT TO CURRENT_USER USING (true);
DROP POLICY IF EXISTS sbx_b2b_sessions_owner ON sbx_b2b_sessions;
CREATE POLICY sbx_b2b_sessions_owner ON sbx_b2b_sessions TO CURRENT_USER USING (true) WITH CHECK (true);

-- The runtime supplies the configured demo bcrypt hash; no literal credential.

-- Reverse only this migration's objects, in foreign-key dependency order.
-- Never cascade into unrelated objects or drop pre-existing application tables.
DROP TABLE IF EXISTS sbx_b2b_sessions;
DROP TABLE IF EXISTS sbx_b2b_login_attempts;
DROP TABLE IF EXISTS sbx_b2b_accounts;
DROP FUNCTION IF EXISTS sbx_b2b_touch_updated_at();

"use client";

import { useRef, useState, type CSSProperties, type FormEvent } from "react";
import { authenticate, errorCatalog, returnPath, SESSION_KEY, tokens, type ErrorCode } from "@/lib/sbx-b2b-login";

const t = tokens;
const emailMessage = "Ingresa un correo electrónico válido. Ejemplo: usuario@empresa.com";
const passwordMessage = "Ingresa tu contraseña.";

function validEmail(emailValue: string): boolean {
  const email = emailValue.trim();
  if (!email || email.length > 254 || /\s/.test(email) || email.includes("..")) return false;
  const parts = email.split("@");
  if (parts.length !== 2 || !parts[0] || parts[0].startsWith(".") || parts[0].endsWith(".")) return false;
  const labels = parts[1].split(".");
  return labels.length >= 2 && labels.every((label) => Boolean(label) && !label.startsWith("-") && !label.endsWith("-"));
}

type IconName = "Mail" | "LockKeyhole" | "Eye" | "EyeOff";
function Icon({ name }: { name: IconName }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      {name === "Mail" && <><rect x="2" y="4" width="20" height="16" rx="2" /><path d="m22 7-10 6L2 7" /></>}
      {name === "LockKeyhole" && <><rect x="4" y="10" width="16" height="12" rx="2" /><path d="M8 10V7a4 4 0 0 1 8 0v3M12 15v2" /></>}
      {name === "Eye" && <><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z" /><circle cx="12" cy="12" r="3" /></>}
      {name === "EyeOff" && <><path d="m3 3 18 18M10.6 5.1A11 11 0 0 1 12 5c6 0 10 7 10 7a14 14 0 0 1-3 3.7M6.3 6.3C3.6 8.2 2 12 2 12s4 7 10 7c1.2 0 2.4-.3 3.5-.8" /></>}
    </svg>
  );
}
const inputStyle: CSSProperties = {
  boxSizing: "border-box", width: "100%", background: t.card_surface, color: t.navy_core,
  border: `1px solid ${t.border_soft}`, borderRadius: t.radius_12,
  padding: `${t.space_16} ${t.space_48}`, font: "inherit",
};
const linkStyle: CSSProperties = {
  color: t.blue_brand_accent, textDecoration: "underline", ...t.text_body_small,
};

export default function SbxB2bLoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [visible, setVisible] = useState(false);
  const [pending, setPending] = useState(false);
  const [emailError, setEmailError] = useState(false);
  const [passwordError, setPasswordError] = useState(false);
  const [error, setError] = useState<{ code: ErrorCode; correlationId?: string } | null>(null);
  const inFlight = useRef(false);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (inFlight.current) return;
    const badEmail = !validEmail(email);
    const badPassword = password.length === 0;
    setEmailError(badEmail);
    setPasswordError(badPassword);
    setError(null);
    if (badEmail || badPassword) return;
    inFlight.current = true;
    setPending(true);
    try {
      const result = await authenticate(email.trim(), password);
      if (result.ok) {
        window.sessionStorage.setItem(SESSION_KEY, result.success.token);
        window.location.assign(returnPath(window.location.search));
      } else {
        setError({ code: result.code, correlationId: result.correlationId });
      }
    } finally {
      setPending(false);
      inFlight.current = false;
    }
  }

  const currentError = error ? errorCatalog[error.code] : null;
  return (
    <main style={{ minHeight: "100dvh", display: "flex", flexDirection: "column", boxSizing: "border-box",
      background: t.warm_surface, color: t.navy_core, fontFamily: t.font_family_base, padding: t.space_24 }}>
      <style>{`
        .sbx-b2b-shell { container-type: inline-size; flex: 1; display: grid; place-items: center; }
        .sbx-b2b-form { width: 100%; max-width: calc(${t.space_64} * 8); }
        .sbx-b2b-focus:focus-visible { outline: 3px solid ${t.blue_brand_accent}; outline-offset: ${t.space_4}; }
        .sbx-b2b-submit:hover:not(:disabled) { background: ${t.green_action_hover} !important; }
        .sbx-b2b-submit:disabled { opacity: .7; cursor: wait; }
        @container (max-width: 480px) { .sbx-b2b-form { max-width: 100%; } }
        @media (forced-colors: active) {
          .sbx-b2b-focus:focus-visible { outline-color: Highlight; }
          .sbx-b2b-submit, .sbx-b2b-field { border: 1px solid ButtonText !important; }
        }
        @media (prefers-reduced-motion: reduce) {
          .sbx-b2b-form * { transition: none !important; animation: none !important; }
        }
      `}</style>
      <header style={{ display: "flex", justifyContent: "flex-end", paddingBottom: t.space_24 }}>
        <strong style={{ textAlign: "right" }}>Backoffice Empresa</strong>
      </header>
      <section className="sbx-b2b-shell" aria-label="Iniciar sesión">
        <form className="sbx-b2b-form" onSubmit={(event) => void submit(event)} noValidate>
          <h1 style={{ ...t.text_section_h2, margin: `0 0 ${t.space_32}` }}>Iniciar sesión</h1>
          <div style={{ marginBottom: t.space_24 }}>
            <label htmlFor="sbx-email" style={{ display: "block", marginBottom: t.space_8, ...t.text_body_small }}>
              Correo electrónico
            </label>
            <div style={{ position: "relative" }}>
              <span aria-hidden="true" style={{ position: "absolute", left: t.space_16, top: t.space_16, color: t.navy_muted }}>
                <Icon name="Mail" />
              </span>
              <input className="sbx-b2b-field sbx-b2b-focus" id="sbx-email" type="email" name="email"
                autoComplete="username" placeholder="ejemplo@empresa.com" maxLength={254} required
                value={email} aria-invalid={emailError} aria-describedby={emailError ? "sbx-email-error" : undefined}
                onChange={(event) => { setEmail(event.target.value); setEmailError(false); }} style={inputStyle} />
            </div>
            {emailError && <p role="alert" id="sbx-email-error" style={{ color: t.error_text, ...t.text_body_small }}>{emailMessage}</p>}
          </div>
          <div>
            <label htmlFor="sbx-password" style={{ display: "block", marginBottom: t.space_8, ...t.text_body_small }}>
              Contraseña
            </label>
            <div style={{ position: "relative" }}>
              <span aria-hidden="true" style={{ position: "absolute", top: t.space_16, left: t.space_16, color: t.navy_muted }}>
                <Icon name="LockKeyhole" />
              </span>
              <input className="sbx-b2b-field sbx-b2b-focus" id="sbx-password" name="password" required
                type={visible ? "text" : "password"} autoComplete="current-password"
                placeholder="Ingresa tu contraseña" value={password}
                aria-invalid={passwordError} aria-describedby={passwordError ? "sbx-password-error" : undefined}
                onChange={(event) => { setPassword(event.target.value); setPasswordError(false); }} style={inputStyle} />
              <button type="button" className="sbx-b2b-focus" aria-label={visible ? "Ocultar contraseña" : "Mostrar contraseña"}
                aria-pressed={visible} onClick={() => setVisible((wasVisible) => !wasVisible)}
                style={{ position: "absolute", right: t.space_8, top: t.space_4, minHeight: t.space_48, minWidth: t.space_48,
                  background: "transparent", border: 0, color: t.navy_muted, cursor: "pointer" }}>
                <Icon name={visible ? "EyeOff" : "Eye"} />
              </button>
            </div>
            {passwordError && <p role="alert" id="sbx-password-error" style={{ color: t.error_text, ...t.text_body_small }}>{passwordMessage}</p>}
            <div style={{ marginTop: t.space_12, textAlign: "right" }}>
              <a className="sbx-b2b-focus" href="#" style={linkStyle} onClick={(event) => event.preventDefault()}>
                ¿Olvidaste tu contraseña?
              </a>
            </div>
          </div>
          {currentError && <div role="alert" style={{ background: t.error_bg, color: t.error_text,
            borderRadius: t.radius_12, padding: t.space_16, marginTop: t.space_24 }}>
            <strong>{currentError.title}</strong>
            <p>{currentError.message}</p>
            <p>{currentError.suggestedAction}</p>
            <p>{currentError.actionLabel}{error?.correlationId ? ` · ${error.correlationId}` : ""}</p>
          </div>}
          <button className="sbx-b2b-submit sbx-b2b-focus" type="submit" disabled={pending} aria-busy={pending}
            style={{ display: "block", width: "100%", marginTop: t.space_24, padding: t.space_16,
              border: 0, borderRadius: t.radius_12, background: t.green_action,
              color: t.card_surface, cursor: "pointer", ...t.text_button }}>
            Acceder
          </button>
          <span role="status" aria-live="polite" style={{ ...t.text_body_small, color: t.navy_muted }}>
            {pending ? "Acceder" : ""}
          </span>
        </form>
      </section>
      <footer style={{ display: "flex", justifyContent: "center", flexWrap: "wrap", gap: t.space_24, paddingTop: t.space_32 }}>
        {["Términos y condiciones", "Política de privacidad", "Contáctanos"].map((label) => (
          <a className="sbx-b2b-focus" key={label} href="#" style={linkStyle}
            onClick={(event) => event.preventDefault()}>{label}</a>
        ))}
      </footer>
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  listReminders,
  type Reminder,
  type ReminderPriority,
} from "@/lib/sbx-rem-list";

const LOGIN_PATH = "/sbx-b2b-login?next=/sbx-rem-list";

export default function SbxRemListPage() {
  const [query, setQuery] = useState("");
  const [priority, setPriority] = useState<ReminderPriority | "">("");
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    let active = true;
    void listReminders(query, priority || undefined)
      .then((result) => {
        if (!active) return;
        if (result.status === 401) {
          window.location.assign(LOGIN_PATH);
          return;
        }
        if (result.status !== 200) {
          setReminders([]);
          setError(true);
          return;
        }
        setReminders(result.reminders);
        setError(false);
      })
      .catch(() => {
        if (!active) return;
        setReminders([]);
        setError(true);
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [query, priority]);

  return (
    <main>
      <h1>Recordatorios</h1>
      <section aria-label="Filtros de recordatorios">
        <label htmlFor="reminder-search">Buscar</label>
        <input
          id="reminder-search"
          type="search"
          value={query}
          onChange={(event) => {
            setLoading(true);
            setQuery(event.target.value);
          }}
        />
        <label htmlFor="reminder-priority">Prioridad</label>
        <select
          id="reminder-priority"
          value={priority}
          onChange={(event) => {
            setLoading(true);
            setPriority(event.target.value as ReminderPriority | "");
          }}
        >
          <option value="">Todas</option>
          <option value="HIGH">Alta</option>
          <option value="MEDIUM">Media</option>
          <option value="LOW">Baja</option>
        </select>
      </section>
      {loading && <p role="status">Cargando recordatorios...</p>}
      {error && <p role="alert">SBX-E-GENERIC</p>}
      {!loading && !error && (
        <ul aria-label="Lista de recordatorios">
          {reminders.map((reminder) => (
            <li key={reminder.id}>
              <span>{reminder.text}</span>{" "}
              <time>{reminder.at}</time>{" "}
              <span>{reminder.priority}</span>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
}

